"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9668],{62052:e=>{e.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a party service over a store.\\n\\nA [Matchmaker] constructs one automatically as `queue.parties`, passing its\\nown clock, id generator and key namespace. Construct one directly only to use\\nparties without a queue.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"options","desc":"`clock`, `id`, `namespace`, `keys`, `maxMembers`, and the expiration values.","lua_type":"any?"}],"returns":[{"desc":"","lua_type":"Party\\n"}],"function_type":"static","source":{"line":136,"path":"src/Party.luau"}},{"name":"get","desc":"Reads a party by id.\\n\\nIf the party holds a queue lock whose ticket has stopped being heartbeaten,\\nthe lock is cleared before returning.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"}],"returns":[{"desc":"`PartyNotFound` if it does not exist.","lua_type":"Result<PartyView>"}],"function_type":"static","source":{"line":167,"path":"src/Party.luau"}},{"name":"getForUser","desc":"The party a user belongs to, or `nil` if they are not in one.\\n\\nA membership record pointing at a deleted party, or at one that no longer\\nlists the user, is cleared and treated as `nil`.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Result<PartyView?>"}],"function_type":"static","source":{"line":211,"path":"src/Party.luau"}},{"name":"create","desc":"Creates a party with `leaderUserId` as its only member and leader.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"leaderUserId","desc":"","lua_type":"number"},{"name":"serverId","desc":"The member\'s current server, used to address match delivery.","lua_type":"string?"}],"returns":[{"desc":"`AlreadyInParty` if the user already belongs to one.","lua_type":"Result<PartyView>"}],"function_type":"static","source":{"line":242,"path":"src/Party.luau"}},{"name":"invite","desc":"Invites a player to the caller\'s party.\\n\\nThe invite is written to an inbox keyed by the target\'s userId, so they can\\nread it from whichever server they are on. Inboxes hold 20 invites, evicting\\nthe oldest, and entries expire after 60 seconds. A second invite from the\\nsame party replaces the first.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"leaderUserId","desc":"","lua_type":"number"},{"name":"targetUserId","desc":"","lua_type":"number"}],"returns":[{"desc":"`NotLeader`, `PartyLocked`, `PartyFull`, or `InvalidTarget` for a self-invite.","lua_type":"Result<PartyInvite>"}],"function_type":"static","source":{"line":298,"path":"src/Party.luau"}},{"name":"listInvites","desc":"A user\'s unexpired invites, oldest first.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"Result<{ PartyInvite }>"}],"function_type":"static","source":{"line":360,"path":"src/Party.luau"}},{"name":"declineInvite","desc":"Removes an invite from a user\'s inbox. Succeeds whether or not the invite was\\nstill present.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"},{"name":"inviteId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"Result<true>"}],"function_type":"static","source":{"line":396,"path":"src/Party.luau"}},{"name":"acceptInvite","desc":"Accepts an invite and joins the party.\\n\\nThe user\'s membership slot is reserved before the party record is touched, so\\naccepting two invites concurrently admits them to exactly one party.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"},{"name":"inviteId","desc":"","lua_type":"string"},{"name":"serverId","desc":"The member\'s current server, used to address match delivery.","lua_type":"string?"}],"returns":[{"desc":"`InviteNotFound`, `AlreadyInParty`, or `PartyUnavailable` if the party filled, queued, or vanished.","lua_type":"Result<PartyView>"}],"function_type":"static","source":{"line":411,"path":"src/Party.luau"}},{"name":"leave","desc":"Removes the caller from their party.\\n\\nIf they were the leader, the longest-standing remaining member inherits. If\\nthey were the last member, the party is deleted.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"}],"returns":[{"desc":"`nil` when the party was deleted. `PartyLocked` while queued.","lua_type":"Result<PartyView?>"}],"function_type":"static","source":{"line":580,"path":"src/Party.luau"}},{"name":"kick","desc":"Removes another member from the caller\'s party. Leader only.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"leaderUserId","desc":"","lua_type":"number"},{"name":"targetUserId","desc":"","lua_type":"number"}],"returns":[{"desc":"`NotLeader`, `PartyLocked`, or `InvalidTarget` if the leader targets themselves.","lua_type":"Result<PartyView?>"}],"function_type":"static","source":{"line":590,"path":"src/Party.luau"}},{"name":"transferLeader","desc":"Hands leadership to another member of the caller\'s party.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"leaderUserId","desc":"","lua_type":"number"},{"name":"targetUserId","desc":"","lua_type":"number"}],"returns":[{"desc":"`NotLeader`, `NotMember` if the target is not in the party, or `PartyLocked`.","lua_type":"Result<PartyView>"}],"function_type":"static","source":{"line":603,"path":"src/Party.luau"}},{"name":"heartbeat","desc":"Refreshes a member\'s records and updates the server they are on.\\n\\nCall this when a member changes servers, otherwise a match involving them is\\nannounced to the server they were on when they joined the party.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"userId","desc":"","lua_type":"number"},{"name":"serverId","desc":"","lua_type":"string?"}],"returns":[{"desc":"`nil` if the user is not in a party.","lua_type":"Result<PartyView?>"}],"function_type":"static","source":{"line":656,"path":"src/Party.luau"}},{"name":"lockQueue","desc":"Locks the party against a queue ticket, freezing its membership. Called by\\n[Matchmaker:enqueueParty].","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"leaderUserId","desc":"","lua_type":"number"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"`PartyLocked` if already queued or the caller is not the leader.","lua_type":"Result<PartyView>"}],"function_type":"static","private":true,"source":{"line":700,"path":"src/Party.luau"}},{"name":"unlockQueue","desc":"Releases the queue lock held against `ticketId`.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"`PartyChanged` if the party is not locked to this ticket.","lua_type":"Result<PartyView>"}],"function_type":"static","private":true,"source":{"line":740,"path":"src/Party.luau"}},{"name":"heartbeatQueue","desc":"Extends a queue lock\'s deadline. Called alongside the ticket\'s own heartbeat;\\nwhen it stops, [Party:get] clears the lock.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"ticketId","desc":"","lua_type":"string"}],"returns":[{"desc":"`PartyChanged` if the party is not locked to this ticket.","lua_type":"Result<PartyView>"}],"function_type":"static","private":true,"source":{"line":777,"path":"src/Party.luau"}},{"name":"markMatched","desc":"Moves a queue lock from `Queued` to `Matched` and extends it to the match\'s\\nlifetime. The party stays locked until acknowledged.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"ticketId","desc":"","lua_type":"string"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"`PartyChanged` if the party is not locked to this ticket.","lua_type":"Result<PartyView>"}],"function_type":"static","private":true,"source":{"line":817,"path":"src/Party.luau"}},{"name":"acknowledgeMatch","desc":"Releases the lock held for a matched party, letting it queue again.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"partyId","desc":"","lua_type":"string"},{"name":"matchId","desc":"","lua_type":"string"}],"returns":[{"desc":"`MatchMismatch` if the party is not locked to this match.","lua_type":"Result<PartyView>"}],"function_type":"static","private":true,"source":{"line":858,"path":"src/Party.luau"}},{"name":"disband","desc":"Deletes the caller\'s party and clears every member\'s membership record.\\nLeader only.","params":[{"name":"self","desc":"","lua_type":"Party"},{"name":"leaderUserId","desc":"","lua_type":"number"}],"returns":[{"desc":"`NotLeader` or `PartyLocked` while queued.","lua_type":"Result<true>"}],"function_type":"static","source":{"line":877,"path":"src/Party.luau"}}],"properties":[],"types":[],"name":"Party","desc":"Party state that persists across servers, stored in MemoryStore.\\n\\nUse this when a party must survive its members being on different servers.\\nTo queue a group of players who are already together on one server,\\n[Matchmaker:enqueueGroup] takes userIds directly and does not touch any of\\nthis. A [Matchmaker] builds its `parties` instance on first access, and\\nnothing is written to the store until a method is called.\\n\\n```lua\\nlocal parties = queue.parties\\n\\nlocal party = Muster.Result.unwrap(parties:create(leaderUserId))\\nparties:invite(leaderUserId, friendUserId)\\n\\n-- On the friend\'s server, which may be a different one:\\nlocal invites = Muster.Result.unwrap(parties:listInvites(friendUserId))\\nparties:acceptInvite(friendUserId, invites[1].id)\\n```\\n\\n### Rules\\n\\n- A player belongs to at most one party. Membership is a single-slot index\\n  per userId written with compare-and-set, so two servers adding the same\\n  player concurrently produce exactly one winner; the loser gets\\n  `AlreadyInParty`.\\n- Parties hold up to `maxMembers` (default 8; a [Matchmaker] passes its\\n  `size.max`).\\n- Only the leader may invite, kick, transfer leadership, disband, or queue\\n  the party.\\n- When the leader leaves, the longest-standing remaining member inherits.\\n  Removing the last member deletes the party.\\n- Invites live in an inbox keyed by the **target** userId, capped at 20 and\\n  expiring after 60 seconds.\\n\\n### While queued\\n\\nA queued party is locked: `invite`, `leave`, `kick`, `transferLeader` and\\n`disband` all return `PartyLocked` until the ticket matches, is cancelled, or\\nexpires. This keeps the roster stable between the matcher reading it and the\\nmatch committing.\\n\\nA lock whose ticket stopped being heartbeaten \u2014 because the server holding it\\ndied \u2014 is cleared the next time the party is read, rather than persisting for\\nthe party\'s full two-hour lifetime.\\n\\n### Records\\n\\nParties expire after 2 hours without activity. Accepting an invite first\\ntakes a 20-second `Reserved` membership slot and only promotes it to `Active`\\nonce the party record has been updated, so a failure between the two leaves a\\nslot that clears itself rather than a player stuck in neither state.","source":{"line":58,"path":"src/Party.luau"}}')}}]);